```
The second test must be kept green by every subsequent step. Commit as "design tokens".

time_utils.s:
Create src/lib/time.ts. Pure functions only, zero imports. Every position in sinc is an INTEGER frame count — never a float second — because float drift is what makes hand-tapped beat markers land one frame off. Seconds appear only at the boundaries (media APIs).

```ts
export const fr_to_sec = (f: number, fps: number) => f / fps;

export const sec_to_fr = (s: number, fps: number) => Math.round(s * fps);

export const conv_fr = (f: number, from: number, to: number) =>
	from === to ? f : Math.round((f * to) / from);

const pad = (n: number) => String(n).padStart(2, '0');

export const tc = (f: number, fps: number) => {
	const r = Math.round(fps);
	const t = Math.max(0, Math.trunc(f));
	return [Math.floor(t / (r * 3600)), Math.floor(t / (r * 60)) % 60, Math.floor(t / r) % 60, t % r]
		.map(pad)
		.join(':');
};

export const snap = (f: number, cands: number[], tol: number) => {
	let best = f;
	let d = tol + 1;
	for (const c of cands) {
		const n = Math.abs(c - f);
		if (n < d || (n === d && c < best)) {
			d = n;
			best = c;
		}
	}
	return d <= tol ? best : f;
};

const COMMON = [23.976, 24, 25, 29.97, 30, 48, 50, 59.94, 60];

export const clean_fps = (f: number) =>
	COMMON.find((c) => Math.abs(c - f) < 0.12) ?? Math.round(f * 1000) / 1000;
```

Why clean_fps: mediabunny's computePacketStats().averagePacketRate is a measured average over a sample of packets, so a 29.97 file reports something like 29.9683. Frame stepping with that value accumulates error over a few minutes and lands on the wrong frame. Snapping to the nearest standard rate fixes it; anything genuinely non-standard falls through unchanged.

Why tc rounds fps: 29.97 timecode is drop-frame in broadcast; sinc deliberately uses non-drop (simply floor the rate) because the display is an operator aid, not a delivery spec. Do not add drop-frame.

TESTS — create src/lib/time.spec.ts FIRST and watch it fail before writing time.ts:
- tc(0, 30) === '00:00:00:00'
- tc(30, 30) === '00:00:01:00'
- tc(3599 * 30 + 29, 30) === '00:59:59:29'
- tc(108000, 30) === '01:00:00:00'
- tc(-5, 30) === '00:00:00:00'
- conv_fr(24, 24, 30) === 30 and conv_fr(7, 30, 30) === 7
- sec_to_fr(1.4833, 30) === 44
- snap(100, [96, 140], 8) === 96 ; snap(100, [80, 140], 8) === 100 ; snap(100, [92, 108], 8) === 92 (tie prefers the lower candidate) ; snap(5, [], 8) === 5
- clean_fps(29.9683) === 29.97 ; clean_fps(30.0004) === 30 ; clean_fps(12.5) === 12.5

Then `pnpm run test:unit -- --run`, `pnpm run check`, `pnpm run lint`. Commit as "time utils".

types_and_store.s:
Create src/lib/types.ts and src/lib/project.svelte.ts.

House rule in effect: stored/serialised object keys are SINGLE LETTERS (this state is persisted to IndexedDB verbatim in a later step). Vars and functions are snake_case. Enum-ish values are single characters.

src/lib/types.ts:
```ts
export type src = {
	i: string; // id
	n: string; // file name
	k: 'v' | 'a' | 'p'; // video / audio / picture
	d: number; // duration, seconds
	f: number; // frames per second (pictures get the project fps at import time)
	w: number; // px
	h: number; // px
};

export type clip = {
	i: string;
	s: string; // src id
	a: number; // in frame, source frames, inclusive
	b: number; // out frame, source frames, inclusive (a === b is a single-frame still)
};

export type track = {
	i: string;
	k: 'v' | 'a';
	n: string; // label, e.g. 'v1'
	m: 0 | 1; // muted
	h: 0 | 1; // hidden from render
};

export type marker = {
	p: number; // project frame
	g: string; // group; '' = hand-tapped. phase 2 fills instrument names
};

export type item = {
	i: string;
	c: string; // clip id
	t: string; // track id
	p: number; // start, project frames
	l: number; // length, project frames
};

export type proj = {
	f: number; // project fps
	w: number;
	h: number;
	r: src[];
	c: clip[];
	t: track[];
	m: marker[];
	x: item[];
};
```

src/lib/project.svelte.ts — the single source of truth. Runes only. Export OBJECTS, never `$state` primitives (a re-exported primitive loses reactivity across module boundaries; the proxied object keeps it).
```ts
import { conv_fr } from './time';
import type { clip, item, marker, proj, src, track } from './types';

export const id = () => Math.random().toString(36).slice(2, 10);

const fresh = (): proj => ({
	f: 30,
	w: 1920,
	h: 1080,
	r: [],
	c: [],
	t: [
		{ i: 'v1', k: 'v', n: 'v1', m: 0, h: 0 },
		{ i: 'a1', k: 'a', n: 'a1', m: 0, h: 0 }
	],
	m: [],
	x: []
});

export const p = $state<proj>(fresh());

export const ui = $state({
	pf: 0, // playhead, project frames
	playing: false,
	mode: 'e' as 'e' | 'c', // edit / clip-maker
	sel: '', // selected timeline item id
	src_sel: '', // selected source id
	zoom: 4, // px per project frame
	scroll: 0, // leftmost visible project frame
	snap: 1 as 0 | 1
});

let past: string[] = [];
let future: string[] = [];

export function commit() {
	past.push(JSON.stringify($state.snapshot(p)));
	if (past.length > 50) past.shift();
	future = [];
}

const apply = (s: string) => Object.assign(p, JSON.parse(s) as proj);

export function undo() {
	const s = past.pop();
	if (!s) return;
	future.push(JSON.stringify($state.snapshot(p)));
	apply(s);
}

export function redo() {
	const s = future.pop();
	if (!s) return;
	past.push(JSON.stringify($state.snapshot(p)));
	apply(s);
}

export function load_proj(next: proj) {
	past = [];
	future = [];
	Object.assign(p, next);
}

export const src_of = (c: clip) => p.r.find((r) => r.i === c.s);
export const clip_of = (x: item) => p.c.find((c) => c.i === x.c);
export const track_of = (x: item) => p.t.find((t) => t.i === x.t);

export function item_len(c: clip) {
	const r = src_of(c);
	return Math.max(1, conv_fr(c.b - c.a + 1, r ? r.f : p.f, p.f));
}

export function add_marker(f: number, g = '') {
	if (p.m.some((m) => m.g === g && Math.abs(m.p - f) < 2)) return;
	commit();
	p.m.push({ p: f, g });
	p.m.sort((a, b) => a.p - b.p);
}

export function del_marker(f: number, g = '') {
	const i = p.m.findIndex((m) => m.g === g && m.p === f);
	if (i < 0) return;
	commit();
	p.m.splice(i, 1);
}

export function add_clip(s: string, a: number, b: number) {
	commit();
	const c: clip = { i: id(), s, a: Math.min(a, b), b: Math.max(a, b) };
	p.c.push(c);
	return c;
}

export function place(cid: string, tid: string, pos: number) {
	const c = p.c.find((x) => x.i === cid);
	if (!c) return;
	commit();
	const x: item = { i: id(), c: cid, t: tid, p: Math.max(0, pos), l: item_len(c) };
	p.x.push(x);
	return x;
}

export function move_item(iid: string, tid: string, pos: number) {
	const x = p.x.find((v) => v.i === iid);
	if (!x) return;
	commit();
	x.t = tid;
	x.p = Math.max(0, pos);
}

export function del_item(iid: string) {
	const i = p.x.findIndex((v) => v.i === iid);
	if (i < 0) return;
	commit();
	p.x.splice(i, 1);
	if (ui.sel === iid) ui.sel = '';
}

export function add_track(k: 'v' | 'a') {
	commit();
	const n = k + String(p.t.filter((t) => t.k === k).length + 1);
	p.t.push({ i: id(), k, n, m: 0, h: 0 });
}

export const total_frames = () => p.x.reduce((n, x) => Math.max(n, x.p + x.l), 0);

// topmost VISIBLE video item covering frame f. later tracks in p.t sit on top.
export function top_at(f: number) {
	let best: item | undefined;
	let rank = -1;
	for (const x of p.x) {
		if (f < x.p || f >= x.p + x.l) continue;
		const t = track_of(x);
		if (!t || t.k !== 'v' || t.h) continue;
		const r = p.t.indexOf(t);
		if (r > rank) {
			rank = r;
			best = x;
		}
	}
	return best;
}
```

Note the undo convention, and follow it everywhere: commit() snapshots the state BEFORE the mutation, so every mutating action calls commit() as its first statement after its guard clauses. Guards come first so a no-op never pushes an undo entry.

TESTS — src/lib/project.svelte.spec.ts (this must be a .svelte.spec.ts so it runs in the CLIENT vitest project; runes require the Svelte compiler, and the node project does not compile .svelte.ts specs with runes support). Write first, watch fail:
- add_marker(10) then add_marker(11) leaves p.m.length === 1 (dedupe window is <2 frames); add_marker(12) makes it 2; add_marker(11, 'kick') makes it 3 (different group, no cross-group dedupe)
- markers stay sorted by p after out-of-order inserts
- item_len: src f=60, clip a=0 b=59 (60 source frames), project f=30 => 30
- item_len never returns 0: src f=60, clip a=0 b=0 => 1
- place() then undo() returns p.x to empty; redo() restores it
- undo() with empty history is a no-op and does not throw
- del_item clears ui.sel when it matches
- top_at: two overlapping items on tracks v1 and v2 (v2 later in p.t) => returns the v2 one; hide v2 (h=1) => returns the v1 one; frame outside both => undefined

Reset state between tests with load_proj(structuredClone(initial)). Run `pnpm run test:unit -- --run`, `pnpm run check`, `pnpm run lint`. Commit as "project state + undo".

media_import.s:
Create src/lib/media.ts — everything that turns a File into something sinc can draw, play and cut.

FIRST, one config change. Open vite.config.ts and in the vitest project named 'client', change:
  include: ['src/**/*.svelte.{test,spec}.{js,ts}']
to:
  include: ['src/**/*.svelte.{test,spec}.{js,ts}', 'src/**/*.browser.{test,spec}.{js,ts}']
and in the project named 'server', change its exclude to also skip them:
  exclude: ['src/**/*.svelte.{test,spec}.{js,ts}', 'src/**/*.browser.{test,spec}.{js,ts}']
Reason: media.ts needs real WebCodecs + real decodeAudioData, which only exist in the browser project (headless chromium via @vitest/browser-playwright), and its spec is not a Svelte component so the .svelte.spec.ts naming would be a lie.

src/lib/media.ts:
```ts
import { ALL_FORMATS, BlobSource, Input, VideoSampleSink } from 'mediabunny';
import { p, id } from './project.svelte';
import { clean_fps } from './time';
import type { src } from './types';

export const files = new Map<string, File>();
export const inputs = new Map<string, Input>();
export const sinks = new Map<string, VideoSampleSink>();
export const els = new Map<string, HTMLVideoElement>(); // preview only
export const bufs = new Map<string, AudioBuffer>();
export const bmps = new Map<string, ImageBitmap>(); // pictures + clip thumbnails

let ac: AudioContext | undefined;
export const audio_ctx = () => (ac ??= new AudioContext());

export async function probe(file: File): Promise<src> {
	const i = id();
	files.set(i, file);

	if (file.type.startsWith('image/')) {
		const bmp = await createImageBitmap(file);
		bmps.set(i, bmp);
		return { i, n: file.name, k: 'p', d: 0, f: p.f, w: bmp.width, h: bmp.height };
	}

	const input = new Input({ formats: ALL_FORMATS, source: new BlobSource(file) });
	inputs.set(i, input);

	const vt = await input.getPrimaryVideoTrack();
	const at = await input.getPrimaryAudioTrack();

	if (at) {
		bufs.set(i, await audio_ctx().decodeAudioData(await file.arrayBuffer()));
	}

	if (!vt) {
		const d = await input.computeDuration();
		return { i, n: file.name, k: 'a', d, f: p.f, w: 0, h: 0 };
	}

	sinks.set(i, new VideoSampleSink(vt));
	const el = document.createElement('video');
	el.src = URL.createObjectURL(file);
	el.muted = true;
	el.playsInline = true;
	el.preload = 'auto';
	els.set(i, el);

	return {
		i,
		n: file.name,
		k: 'v',
		d: await vt.computeDuration(),
		f: clean_fps((await vt.computePacketStats(100)).averagePacketRate),
		w: await vt.getDisplayWidth(),
		h: await vt.getDisplayHeight()
	};
}

// frame-exact decode. the +0.5 lands mid-frame so float rounding can never
// pick the neighbouring frame at a boundary — this is what makes clip edges surgical.
export async function frame_at(sid: string, f: number, fps: number) {
	const sink = sinks.get(sid);
	if (!sink) return bmps.get(sid) ?? null;
	return await sink.getSample((f + 0.5) / fps);
}

export async function thumb(sid: string, f: number, fps: number) {
	const key = sid + ':' + f;
	const hit = bmps.get(key);
	if (hit) return hit;
	const bmp = bmps.get(sid);
	if (bmp) return bmp;
	const smp = await frame_at(sid, f, fps);
	if (!smp || !('toVideoFrame' in smp)) return null;
	const out = await createImageBitmap(smp.toVideoFrame(), { resizeWidth: 160, resizeQuality: 'low' });
	smp.close();
	bmps.set(key, out);
	return out;
}

// min/max envelope, two floats per bucket, for waveform painting
export function peaks(buf: AudioBuffer, n: number) {
	const d = buf.getChannelData(0);
	const step = Math.max(1, Math.floor(d.length / n));
	const out = new Float32Array(n * 2);
	for (let i = 0; i < n; i++) {
		let lo = 0;
		let hi = 0;
		for (let j = i * step, e = Math.min(d.length, j + step); j < e; j++) {
			if (d[j] < lo) lo = d[j];
			if (d[j] > hi) hi = d[j];
		}
		out[i * 2] = lo;
		out[i * 2 + 1] = hi;
	}
	return out;
}

// rebuild the non-serialisable side-tables after an IndexedDB restore
export async function rehydrate(r: src, file: File) {
	files.set(r.i, file);
	if (r.k === 'p') return void bmps.set(r.i, await createImageBitmap(file));
	const input = new Input({ formats: ALL_FORMATS, source: new BlobSource(file) });
	inputs.set(r.i, input);
	const vt = await input.getPrimaryVideoTrack();
	if (await input.getPrimaryAudioTrack())
		bufs.set(r.i, await audio_ctx().decodeAudioData(await file.arrayBuffer()));
	if (!vt) return;
	sinks.set(r.i, new VideoSampleSink(vt));
	const el = document.createElement('video');
	el.src = URL.createObjectURL(file);
	el.muted = true;
	el.playsInline = true;
	el.preload = 'auto';
	els.set(r.i, el);
}
```

Traps this step must respect:
- Video <video> elements are ALWAYS muted. All audible sound in sinc comes from WebAudio AudioBuffers, so there is exactly one clock and one mixer. Never unmute an element.
- decodeAudioData CONSUMES the ArrayBuffer; always pass a fresh `await file.arrayBuffer()`, never a reused one.
- audio_ctx() is lazy because constructing an AudioContext before a user gesture leaves it suspended; the transport resumes it on first play.
- Pictures are given f = p.f at import so every frame conversion elsewhere is branch-free. Changing project fps later rescales existing stills; that is accepted, do not add a special case.

TESTS — src/lib/media.browser.spec.ts, written first, run with `pnpm run test:unit -- --run`. Synthesize the fixture instead of committing a binary:
```ts
import { BufferTarget, CanvasSource, Mp4OutputFormat, Output, QUALITY_LOW } from 'mediabunny';
import { expect, test } from 'vitest';
import { peaks, probe } from './media';

async function fixture() {
	const cv = document.createElement('canvas');
	cv.width = 320;
	cv.height = 240;
	const ctx = cv.getContext('2d')!;
	const out = new Output({ format: new Mp4OutputFormat(), target: new BufferTarget() });
	const vs = new CanvasSource(cv, { codec: 'avc', bitrate: QUALITY_LOW });
	out.addVideoTrack(vs, { frameRate: 30 });
	await out.start();
	for (let f = 0; f < 30; f++) {
		ctx.fillStyle = f % 2 ? '#fff' : '#000';
		ctx.fillRect(0, 0, 320, 240);
		await vs.add(f / 30, 1 / 30);
	}
	await out.finalize();
	return new File([out.target.buffer!], 'fix.mp4', { type: 'video/mp4' });
}

test('probe reads a real mp4', async () => {
	const r = await probe(await fixture());
	expect(r.k).toBe('v');
	expect(r.w).toBe(320);
	expect(r.h).toBe(240);
	expect(r.f).toBe(30);
	expect(r.d).toBeCloseTo(1, 1);
});

test('peaks envelope', () => {
	const ctx = new OfflineAudioContext(1, 400, 48000);
	const buf = ctx.createBuffer(1, 400, 48000);
	buf.getChannelData(0).fill(0.5, 0, 200);
	buf.getChannelData(0).fill(-0.25, 200, 400);
	const pk = peaks(buf, 2);
	expect(pk[1]).toBeCloseTo(0.5, 2);
	expect(pk[2]).toBeCloseTo(-0.25, 2);
});
```
Note the fixture writes literal hex to a CANVAS, not to CSS — the "no raw hex" test from step design_tokens only scans .svelte files, so this is fine.
Then `pnpm run check`, `pnpm run lint`. Commit as "media import".

keybinds.s:
Create src/lib/keys.svelte.ts and src/lib/ui/settings.svelte, and wire the global handler in src/routes/+page.svelte.

src/lib/keys.svelte.ts:
```ts
export type act =
	| 'play' | 'mark' | 'clip' | 'in' | 'out'
	| 'prev' | 'next' | 'add' | 'snap' | 'undo' | 'redo' | 'del' | 'esc';

export const def: Record<act, string> = {
	play: ' ',
	mark: 'b',
	clip: 'c',
	in: 's',
	out: 'e',
	prev: 'ArrowLeft',
	next: 'ArrowRight',
	add: 'a',
	snap: 'n',
	undo: 'z',
	redo: 'y',
	del: 'Delete',
	esc: 'Escape'
};

const KEY = 'sinc_keys';

const saved = (): Partial<Record<act, string>> => {
	try {
		return JSON.parse(localStorage.getItem(KEY) ?? '{}');
	} catch {
		return {};
	}
};

export const binds = $state<Record<act, string>>({ ...def, ...saved() });

export function set_bind(a: act, k: string) {
	binds[a] = k;
	localStorage.setItem(KEY, JSON.stringify($state.snapshot(binds)));
}

export function reset_binds() {
	Object.assign(binds, def);
	localStorage.removeItem(KEY);
}

// pure: exported separately so it is unit-testable without a DOM event loop
export function match(
	key: string,
	tag: string,
	editable: boolean,
	ctrl: boolean,
	b: Record<act, string> = def
): act | null {
	if (editable || tag === 'INPUT' || tag === 'TEXTAREA' || tag === 'SELECT') return null;
	const found = (Object.keys(b) as act[]).find(
		(a) => b[a].toLowerCase() === key.toLowerCase()
	);
	if (!found) return null;
	if (ctrl) return found === 'undo' || found === 'redo' ? found : null;
	return found === 'undo' || found === 'redo' ? null : found;
}

export function from_event(e: KeyboardEvent) {
	const t = e.target as HTMLElement | null;
	return match(
		e.key,
		t?.tagName ?? '',
		!!t?.isContentEditable,
		e.ctrlKey || e.metaKey,
		binds
	);
}
```
Design notes the executor must not "improve": undo/redo REQUIRE ctrl/cmd (so plain `z` stays free), every other action REQUIRES no modifier (so browser shortcuts keep working). match() takes primitives rather than a KeyboardEvent so its test needs no DOM.

