viewport.svelte — one <canvas> sized p.w × p.h, CSS `h-full w-full object-contain`, drawn by a single requestAnimationFrame loop that owns the playhead:
```ts
let cv: HTMLCanvasElement;
let raf = 0;
let t0 = 0;
let f0 = 0;

function tick(now: number) {
	if (ui.playing) {
		ui.pf = f0 + Math.round(((now - t0) / 1000) * p.f);
		if (ui.pf >= total_frames()) stop();
	}
	draw();
	raf = requestAnimationFrame(tick);
}

$effect(() => {
	raf = requestAnimationFrame(tick);
	return () => cancelAnimationFrame(raf);
});
```
The playhead is derived from wall-clock elapsed time (t0/f0 captured at play), NOT incremented per frame — a dropped rAF frame must not desync the picture from the audio.

draw():
```ts
function draw() {
	const ctx = cv.getContext('2d')!;
	ctx.fillStyle = '#000';
	ctx.fillRect(0, 0, p.w, p.h);
	const x = top_at(ui.pf);
	if (!x) return;
	const c = clip_of(x);
	const r = c && src_of(c);
	if (!c || !r) return;

	const src_f = c.a + conv_fr(ui.pf - x.p, p.f, r.f);
	const pic = bmps.get(r.i);
	if (pic) return void fit(ctx, pic, pic.width, pic.height);

	const el = els.get(r.i);
	if (!el || el.readyState < 2) return;
	const want = (src_f + 0.5) / r.f;
	if (Math.abs(el.currentTime - want) > 0.15) el.currentTime = want;
	if (ui.playing && el.paused) void el.play();
	if (!ui.playing && !el.paused) el.pause();
	fit(ctx, el, r.w, r.h);
}
```
fit() is letterbox maths: `const s = Math.min(p.w / sw, p.h / sh)` then drawImage centred at `(p.w - sw*s)/2, (p.h - sh*s)/2`. Never stretch.

// ponytail: preview seeks the <video> element (±0.15s tolerance), so it is smooth but not frame-exact. Frame-exact decode is used only where it matters — the clip maker and the render. Tighten to VideoSampleSink here only if scrubbing visibly lies.

Audio scheduling (same component, exported helpers or a small src/lib/audio.ts if it reads better — either is fine, do not create both):
```ts
let nodes: AudioBufferSourceNode[] = [];

function schedule() {
	const ac = audio_ctx();
	const t = ac.currentTime + 0.05; // small lead so the first node is not late
	for (const x of p.x) {
		const tr = track_of(x);
		const c = clip_of(x);
		const r = c && src_of(c);
		if (!tr || tr.m || !c || !r) continue;
		const buf = bufs.get(r.i);
		if (!buf) continue;
		const start_f = Math.max(x.p, ui.pf);
		const off = (c.a + conv_fr(start_f - x.p, p.f, r.f)) / r.f;
		const dur = (x.p + x.l - start_f) / p.f;
		if (dur <= 0) continue;
		const n = ac.createBufferSource();
		n.buffer = buf;
		n.connect(ac.destination);
		n.start(t + (start_f - ui.pf) / p.f, off, dur);
		nodes.push(n);
	}
}

function clear_audio() {
	for (const n of nodes) { try { n.stop(); } catch { /* already ended */ } }
	nodes = [];
}
```
play(): `await audio_ctx().resume()` first (an AudioContext created before a gesture is suspended), then `t0 = performance.now(); f0 = ui.pf; ui.playing = true; schedule();`
stop(): `ui.playing = false; clear_audio();`
Any change to ui.pf while playing (a scrub) must clear_audio() and schedule() again — put that in the seek helper, not in a `$effect` on ui.pf (an effect would fire on every one of the 30 frame updates per second the loop itself writes).

